var hold [][]byte

func main() {
	for range 20 {
		hold = append(hold, make([]byte, 1<<20)) // 20 MiB live
	}
	hold = nil
	runtime.GC()
	samples := []metrics.Sample{
		{Name: "/gc/heap/allocs:bytes"},
		{Name: "/memory/classes/heap/objects:bytes"},
	}
	metrics.Read(samples)
	fmt.Printf("allocs=%d MiB objects=%d MiB\n", samples[0].Value.Uint64()>>20, samples[1].Value.Uint64()>>20)
}
